console.log(typeof legacy); // "undefined" — var exists up here, value not yet
var legacy = 'old';

try {
  console.log(shiny);   // never runs
  let shiny = 'new';    // from its declaration's start to this line: the dead zone
} catch (e) {
  console.log(e.name);  // "ReferenceError"
}

const user = { name: 'Maya' };
user.role = 'frontend';        // works — const binds the NAME, not the object's contents
console.log(user.role);        // "frontend"

const frozen = Object.freeze({ tier: 'pro' });
try { frozen.tier = 'enterprise'; } catch (e) { console.log(e.name); } // "TypeError" in strict mode
console.log(frozen.tier);      // "pro" — and freeze is shallow anyway

const varFns = [];
for (var i = 0; i < 3; i++) varFns.push(() => i);

const letFns = [];
for (let j = 0; j < 3; j++) letFns.push(() => j);

console.log(varFns.map((f) => f())); // [3, 3, 3] — one shared i
console.log(letFns.map((f) => f())); // [0, 1, 2] — a fresh j per iteration

